// Smart Pointer (Memory)
std::unique_ptr<int> up(new int(42));
// No need for 'delete'

// Lock Guard (Concurrency)
std::mutex mtx;
{
    std::lock_guard<std::mutex> lock(mtx);
    // Resource is locked...
} // Lock automatically released

// Custom RAII (File Handle)
class FileHandle {
    FILE* fp;
public:
    FileHandle(const char* name, const char* mode)
        : fp(fopen(name, mode)) {}
    ~FileHandle() { if (fp) fclose(fp); }
};

// Standard Library Scope Guard (C++23)
auto guard = std::scope_exit([]{ 
    cleanup_function(); 
});
